import{_ as s,k as t,a6 as a,j as i}from"./chunks/framework.W_BvR9CP.js";const n="/andexdb/assets/main_menu-hovering_over_settings_button.CZHBEAko.png",o="/andexdb/assets/settings-hovering_over_tpa_system_settings_button.BGRiN4jU.png",l="/andexdb/assets/settings-tpa_system_settings-hovering_over_enabled_enable_tpa_system_toggle.YoZVJqPi.png",r="/andexdb/assets/settings-tpa_system_settings-hovering_over_save_button.drTqU7ot.png",k=JSON.parse(`{"title":"TPA System (Pre 1.33.0)","description":"The add-on's TPA system (Pre 1.33.0).","frontmatter":{"title":"TPA System (Pre 1.33.0)","nav_order":4,"description":"The add-on's TPA system (Pre 1.33.0).","hidden":true,"mentions":["8Crafter"]},"headers":[{"level":2,"title":"How to enable the TPA system","slug":"how-to-enable-the-tpa-system","link":"#how-to-enable-the-tpa-system","children":[]},{"level":2,"title":"How to use the TPA/teleport request system","slug":"how-to-use-the-tpa-teleport-request-system","link":"#how-to-use-the-tpa-teleport-request-system","children":[]}],"relativePath":"systems/tpa_(Pre_1.33.0).md","filePath":"systems/tpa_(Pre_1.33.0).md"}`),h={name:"systems/tpa_(Pre_1.33.0).md"};function p(d,e,m,c,u,y){return i(),t("div",null,e[0]||(e[0]=[a('<div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>This page only applies to versions of the add-on prior to v1.33.0.</p><p>If you are using a version from v1.33.0 to v1.34.x, please see the <a href="./../systems/tpa_(Pre_1.35.0)">TPA System (Pre 1.35.0)</a> page.</p><p>If you are using v1.35.0 or newer, please see the <a href="./../systems/tpa">TPA System</a> page.</p></div><p>Any player can use the TP request system, regardless of permissions. The TP request system is disabled by default, so make sure to turn it on in settings.</p><h2 id="how-to-enable-the-tpa-system" tabindex="-1">How to enable the TPA system <a class="header-anchor" href="#how-to-enable-the-tpa-system" aria-label="Permalink to &quot;How to enable the TPA system&quot;">​</a></h2><ol><li><p>Open the <a href="./../main-menu/main-menu">Main Menu</a> (use the <a href="./../commands-list/-mainmenu"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\mainmenu</span></code></a> command or the <a href="./../items/main-menu">Main Menu stick</a>).</p></li><li><p>Scroll down and click &quot;Settings&quot;.</p><p><img src="'+n+'" alt="Main Menu - Hovering Over Settings Button"></p></li><li><p>Scroll down and click &quot;TPA System Settings&quot;.</p><p><img src="'+o+'" alt="Settings - Hovering Over TPA System Settings Button"></p></li><li><p>Enable the <a href="./../settings/tpa-system#enable-tpa-system"><code class="shiki"><span>Enable TPA System</span></code></a> toggle.</p><p><img src="'+l+'" alt="Settings - TPA System Settings - Hovering Over Enabled &quot;Enable TPA System&quot; Toggle"></p></li><li><p>Click the &quot;Save&quot; button.</p><p><img src="'+r+'" alt="Settings - TPA System Settings - Hovering Over Save Button"></p></li></ol><h2 id="how-to-use-the-tpa-teleport-request-system" tabindex="-1">How to use the TPA/teleport request system <a class="header-anchor" href="#how-to-use-the-tpa-teleport-request-system" aria-label="Permalink to &quot;How to use the TPA/teleport request system&quot;">​</a></h2><ul><li>Use <a href="./../commands-list/-tpa"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpa</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;"> &lt;</span><span style="--shiki-light:hsl(201, 98%, 20%);--shiki-dark:#9CDCFE;">player</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">: </span><span style="--shiki-light:hsl(99, 28%, 27%);--shiki-dark:#B5CEA8;">target</span><span style="--shiki-light:hsl(168, 53%, 45%);--shiki-dark:#4EC9B0;">&gt;</span></code></a> to request to teleport to a player (ex. <code class="shiki"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"></span><a href="./../commands-list/-tpa"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">\\tpa</span></a> <span style="--shiki-light:#A31515;--shiki-dark:#CE9178;">Andexter8</span></code> or <code class="shiki"><span style="--shiki-light:#000000;--shiki-dark:#D4D4D4;"></span><a href="./../commands-list/-tpa"><span style="--shiki-light:#AF00DB;--shiki-dark:#C586C0;">\\tpa</span></a> <span style="--shiki-light:#267F99;--shiki-dark:#4EC9B0;">@r</span></code>). This will send a message to that player. If they type <code class="shiki"><span>n</span></code> in chat or do nothing for 1 minute, the request will be denied. If they type <code class="shiki"><span>y</span></code> in chat, you will be teleported to them.</li><li>You can configure a <a href="./../settings/general#pvp-cooldown">PVP cooldown</a> in settings, this will cause the players to be unable to use any of the teleport commands (ex. <a href="./../commands-list/-tpa"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\tpa</span></code></a>, <a href="./../commands-list/-spawn"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\spawn</span></code></a>, and <a href="./../commands-list/-home"><code class="shiki"><span style="--shiki-light:hsl(207, 61%, 41%);--shiki-dark:#569CD6;">\\home</span></code></a>) for the specified amount of time after they are hit by another player.</li></ul>',6)]))}const _=s(h,[["render",p]]);export{k as __pageData,_ as default};
